type TigrisResponse<T, E = Error> = {
    data: T;
    error?: never;
} | {
    error: E;
    data?: never;
};

type TigrisStorageResponse<T, E = Error> = TigrisResponse<T, E>;

/**
 * Discriminated upload contract returned by `getSignedUploadUrl`.
 *
 * PUT: simple presigned URL. Submit the body as the request payload,
 * including any required headers (notably `Content-Type` when one was
 * baked into the signature).
 *
 * POST: S3 POST policy. Submit a `multipart/form-data` request with the
 * provided `fields` as hidden inputs (verbatim, in order), followed by
 * the `file` input last.
 */
type SignedUploadUrlResponse = {
    method: 'PUT';
    url: string;
    headers?: Record<string, string>;
    expiresIn: number;
} | {
    method: 'POST';
    url: string;
    fields: Record<string, string>;
    expiresIn: number;
};

type UploadOptions = {
    access?: 'public' | 'private';
    addRandomSuffix?: boolean;
    allowOverwrite?: boolean;
    contentType?: string;
    contentDisposition?: 'attachment' | 'inline';
    url?: string;
    multipart?: boolean;
    partSize?: number;
    /**
     * Maximum number of concurrent part uploads for multipart uploads
     * @default 4
     */
    concurrency?: number;
    onUploadProgress?: (progress: UploadProgress) => void;
};
type UploadProgress = {
    loaded: number;
    total: number;
    percentage: number;
};
type UploadResponse = {
    contentDisposition?: string;
    contentType?: string;
    modified: Date;
    name: string;
    size: number;
    url: string;
};
declare function upload(name: string, data: File | Blob, options?: UploadOptions): Promise<TigrisStorageResponse<UploadResponse, Error>>;
type UploadToSignedUrlOptions = {
    contentType?: string;
    onUploadProgress?: (progress: UploadProgress) => void;
};
/**
 * Uploads a file using the contract returned by `getSignedUploadUrl`.
 * Branches on `signed.method`: PUT sends the body as the request payload
 * (applying any required headers), POST submits a multipart/form-data
 * body with the policy `fields` followed by the `file` input.
 */
declare function uploadToSignedUrl(name: string, data: File | Blob, signed: SignedUploadUrlResponse, options?: UploadToSignedUrlOptions): Promise<TigrisStorageResponse<UploadResponse, Error>>;

export { type SignedUploadUrlResponse, type UploadOptions, type UploadProgress, type UploadResponse, type UploadToSignedUrlOptions, executeWithConcurrency, upload, uploadToSignedUrl };

